#' Design Effect
#'
#' 
#' @param tuto .
#' @param mode 'variances': inserire la varianza dello stimatore nel piano
#'   complesso e nel SCR di riferimento, il modulo calcola Deff come rapporto.
#'   'formula': usa una formula analitica per uno dei piani standard
#'   (sistematico, a più stadi, a grappoli, stratificato) coerenti con la slide
#'   39.
#' @param var_complex .
#' @param var_srs .
#' @param plan Piano di campionamento per cui calcolare il Deff teorico.
#' @param N .
#' @param n_total .
#' @param rho .
#' @param n_within .
#' @param L .
#' @param R2 .
#' @param n_srs Numerosità n, letta in due modi: se è la numerosità del
#'   casuale semplice da eguagliare, il piano complesso ne richiede n_complex =
#'   Deff · n; se è un campione già raccolto col piano complesso, vale quanto
#'   n_eff = n / Deff unità di un casuale semplice.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$inputs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$result} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$inputs$asDF}
#'
#' \code{as.data.frame(results$inputs)}
#'
#' @export
deff <- function(
    tuto = TRUE,
    mode = "variances",
    var_complex = 1,
    var_srs = 1,
    plan = "systematic",
    N = 1000,
    n_total = 100,
    rho = 0.1,
    n_within = 10,
    L = 4,
    R2 = 0.3,
    n_srs = 100) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("deff requires jmvcore to be installed (restart may be required)")


    options <- deffOptions$new(
        tuto = tuto,
        mode = mode,
        var_complex = var_complex,
        var_srs = var_srs,
        plan = plan,
        N = N,
        n_total = n_total,
        rho = rho,
        n_within = n_within,
        L = L,
        R2 = R2,
        n_srs = n_srs)

    analysis <- deffClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

